149:     private async Task<ChainResponse> ReverseInsideTransactionAsync(string reference, string? reason, CancellationToken cancellationToken)
150:     {
151:         var clientId = currentClient.ClientId;
152:         var now = DateTimeOffset.UtcNow;
153: 
154:         //Getting the original chain with its legs, their entries and accounts
155:         var original = await dbContext.TransactionChains
156:             .Include(c => c.Legs).ThenInclude(l => l.Entries).ThenInclude(e => e.Account)
157:             .SingleOrDefaultAsync(c => c.Reference == reference, cancellationToken)
158:             ?? throw new ChainNotFoundException($"Chain '{reference}' was not found.");
159: 
160:         if (original.Status != TransactionStatus.Success)
161:             throw new ChainNotReversibleException(
162:                 $"Only successful chains can be reversed; '{original.Reference}' is {original.Status}.");
163:         if (original.ReversesChainId is not null)
164:             throw new ChainNotReversibleException(
165:                 $"'{original.Reference}' is itself a reversal and cannot be reversed.");
166: 
167:         //Insert the reversal chain first: the unique reverses_chain_id refuses a second reversal before any work
168:         var reversal = new TransactionChain
169:         {
170:             Reference = TransactionReference.Generate("CHN"),
171:             InitiatedBy = clientId,
172:             // Reversals carry no client key; a generated one keeps the (client, key) index from treating two
173:             // reversals by the same client as duplicates. reverses_chain_id is the real guard.
174:             IdempotencyKey = $"REVERSAL-{Guid.NewGuid()}",
175:             Status = TransactionStatus.Pending,
176:             Narration = reason ?? $"Reversal of {original.Reference}",
177:             ReversesChainId = original.Id,
178:             CreatedAt = now,
179:         };
180:         dbContext.TransactionChains.Add(reversal);
181:         try
182:         {
183:             await dbContext.SaveChangesAsync(cancellationToken);
184:         }
185:         catch (DbUpdateException ex) when (ex.InnerException is PostgresException
186:         {
187:             SqlState: PostgresErrorCodes.UniqueViolation, ConstraintName: ReversesChainIndex
188:         })
189:         {
190:             throw new ChainAlreadyReversedException($"Chain '{original.Reference}' has already been reversed.", ex);
191:         }
192: 
193:         //Lock the accounts the reversing legs debit (each original leg's credit side), once each, ascending order
194:         foreach (var number in original.Legs
195:                      .Select(l => l.Entries.Single(e => e.EntryType == EntryType.Credit).Account.AccountNumber)
196:                      .Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal))
197:         {
198:             await legPoster.LockAccountAsync(number, cancellationToken);
199:         }
200: 
201:         //Reverse each leg, last leg first (e.g. Tax, Fee, Principal)
202:         var reversingLegs = new List<ChainLegResponse>();
203:         var lastFirst = original.Legs.OrderByDescending(l => l.Sequence).ToList();
204:         for (var i = 0; i < lastFirst.Count; i++)
205:         {
206:             var originalLeg = lastFirst[i];
207:             var sequence = i + 1;
208:             var envelope = new Transaction
209:             {
210:                 Reference = TransactionReference.Generate(),
211:                 IdempotencyKey = $"chain:{reversal.Id}:{sequence}",
212:                 InitiatedBy = clientId,
213:                 Status = TransactionStatus.Pending,
214:                 Narration = reason ?? $"Reversal of {originalLeg.Reference}",
215:                 CreatedAt = now,
216:                 Chain = reversal,
217:                 Sequence = sequence,
218:                 Purpose = originalLeg.Purpose,
219:             };
220: 
221:             await legReverser.ReverseLegAsync(originalLeg, envelope, reason, now, cancellationToken);
222: 
223:             var originalDebit = originalLeg.Entries.Single(e => e.EntryType == EntryType.Debit);
224:             var originalCredit = originalLeg.Entries.Single(e => e.EntryType == EntryType.Credit);
225:             reversingLegs.Add(new ChainLegResponse(sequence, envelope.Purpose!.Value.ToString(), envelope.Reference,
226:                 originalCredit.Account.AccountNumber, originalDebit.Account.AccountNumber,
227:                 SupportedCurrencies.ToCurrencyScale(originalDebit.Amount, originalDebit.Currency), originalDebit.Currency,
228:                 envelope.Status.ToString()));
229:         }
230: 
231:         reversal.Status = TransactionStatus.Success;
232:         reversal.CompletedAt = DateTimeOffset.UtcNow;
233:         RecordChainAudit(reversal, AuditActions.ChainReversed, reversingLegs.Sum(l => l.Amount), reversingLegs[0].Currency);
234:         await dbContext.SaveChangesAsync(cancellationToken);
235: 
236:         return ToResponse(reversal, reversingLegs, reversesReference: original.Reference, reversedByReference: null);
237:     }
