239:     private async Task<List<ChainLegResponse>> PostLegsAsync(
240:         TransactionChain chain, List<Leg> legs, string? narration, string? clientId, DateTimeOffset now, CancellationToken cancellationToken)
241:     {
242:         // Lock every debited account once, in ascending ordinal account-number order, before posting anything:
243:         // any two chains lock shared accounts in the same order, so they cannot deadlock (decision #45).
244:         // An account that does not exist is reported by LegPoster at its leg.
245:         var lockedPayers = new Dictionary<string, Account>(StringComparer.Ordinal);
246:         foreach (var number in legs.Select(l => l.Spec.DebitAccountNumber).Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal))
247:         {
248:             if (await legPoster.LockAccountAsync(number, cancellationToken) is { } account)
249:                 lockedPayers[number] = account;
250:         }
251: 
252:         // One balance per paying account, derived up front. Money a payer receives earlier in the same chain is
253:         // not counted: it must already afford everything it pays (decision #45).
254:         var available = new Dictionary<string, decimal>(StringComparer.Ordinal);
255:         foreach (var (number, account) in lockedPayers)
256:             available[number] = await legPoster.BalanceAsync(account, cancellationToken);
257:         var paid = new Dictionary<string, decimal>(StringComparer.Ordinal);
258: 
259:         string? chainCurrency = null;
260:         var posted = new List<ChainLegResponse>();
261:         for (var i = 0; i < legs.Count; i++)
262:         {
263:             var (spec, purpose) = legs[i];
264:             var sequence = i + 1;
265:             var leg = new Transaction
266:             {
267:                 Reference = TransactionReference.Generate(),
268:                 // Generated, so leg keys can never collide with a client's own keys (those may not start with "chain:").
269:                 IdempotencyKey = $"chain:{chain.Id}:{sequence}",
270:                 InitiatedBy = clientId,
271:                 Status = TransactionStatus.Pending,
272:                 Narration = narration is null ? purpose.ToString() : $"{narration} · {purpose}",
273:                 CreatedAt = now,
274:                 Chain = chain,
275:                 Sequence = sequence,
276:                 Purpose = purpose,
277:             };
278:             dbContext.Transactions.Add(leg);
279: 
280:             try
281:             {
282:                 // Per-leg rules, as for a transfer (decision #45); the payer's balance is checked below for the chain.
283:                 var debit = await legPoster.PostLegAsync(leg, spec, checkBalance: false, now, cancellationToken);
284:                 var credit = await dbContext.Accounts.SingleAsync(a => a.AccountNumber == spec.CreditAccountNumber, cancellationToken);
285: 
286:                 if (purpose is LegPurpose.Fee or LegPurpose.Tax && credit.AccountClass != AccountClass.System)
287:                     throw new LegRejectedException($"{purpose} legs must credit a system account");
288: 
289:                 chainCurrency ??= debit.CurrencyCode;
290:                 if (debit.CurrencyCode != chainCurrency)
291:                     throw new LegRejectedException("All legs in a chain must use the same currency");
292: 
293:                 var floor = LegPoster.FloorFor(debit)
294:                     ?? throw new LegRejectedException($"Unrecognized account class: {debit.AccountClass}");
295:                 paid[spec.DebitAccountNumber] = paid.GetValueOrDefault(spec.DebitAccountNumber) + spec.Amount;
296:                 if (available[spec.DebitAccountNumber] - paid[spec.DebitAccountNumber] < floor)
297:                     throw new LegRejectedException("Insufficient Account Balance");
298: 
299:                 // Audit, committed with the postings: the existing transfer action, one row per leg.
300:                 auditLogger.Record(new AuditLog
301:                 {
302:                     Action = AuditActions.Transfer,
303:                     EntityType = nameof(Transaction),
304:                     EntityId = leg.Reference,
305:                     DebitAccountNumber = spec.DebitAccountNumber,
306:                     CreditAccountNumber = spec.CreditAccountNumber,
307:                     Amount = spec.Amount,
308:                     Currency = debit.CurrencyCode,
309:                     Status = leg.Status.ToString(),
310:                 });
311: 
312:                 posted.Add(new ChainLegResponse(sequence, purpose.ToString(), leg.Reference, spec.DebitAccountNumber,
313:                     spec.CreditAccountNumber, SupportedCurrencies.ToCurrencyScale(spec.Amount, debit.CurrencyCode),
314:                     debit.CurrencyCode, leg.Status.ToString()));
315:             }
316:             catch (LegRejectedException rejected)
317:             {
318:                 throw new ChainRejectedException(sequence, rejected.Message);
319:             }
320: 
321:             // Save each leg, so its id exists and its entries are visible to later reads in this transaction.
322:             await dbContext.SaveChangesAsync(cancellationToken);
323:         }
324: 
325:         return posted;
326:     }
