329:     // same-key retry stored its own chain in the meantime, return that one instead.
330:     private async Task<ChainResponse> StoreFailedAsync(
331:         ChainRequest request, string? clientId, string requestHash, string reference, DateTimeOffset now,
332:         ChainRejectedException rejection, CancellationToken cancellationToken)
333:     {
334:         dbContext.ChangeTracker.Clear();
335:         var failed = new TransactionChain
336:         {
337:             Reference = reference,
338:             InitiatedBy = clientId,
339:             IdempotencyKey = request.IdempotencyKey,
340:             RequestHash = requestHash,
341:             Status = TransactionStatus.Failed,
342:             Narration = request.Narration,
343:             FailureReason = rejection.Message,
344:             FailedSequence = rejection.Sequence,
345:             CreatedAt = now,
346:             CompletedAt = DateTimeOffset.UtcNow,
347:         };
348:         dbContext.TransactionChains.Add(failed);
349:         RecordChainAudit(failed, AuditActions.ChainPosted, request.Legs.Sum(l => l.Amount), currency: null);
350: 
351:         try
