364:     // The key is already taken by this client: same legs -> the stored chain; different legs -> 409.
365:     private async Task<ChainResponse> ReplayAsync(
366:         string? clientId, string idempotencyKey, string requestHash, CancellationToken cancellationToken)
367:     {
368:         dbContext.ChangeTracker.Clear();
369:         var stored = await dbContext.TransactionChains.AsNoTracking()
370:             .Include(c => c.ReversesChain)
371:             .SingleAsync(c => c.InitiatedBy == clientId && c.IdempotencyKey == idempotencyKey, cancellationToken);
372: 
373:         if (stored.RequestHash != requestHash)
374:             throw new DuplicateIdempotencyKeyException(
375:                 $"Idempotency key '{idempotencyKey}' was already used for a different request.");
376: 
377:         return await LoadResponseAsync(stored, cancellationToken);
378:     }
