380:     private async Task<ChainResponse> LoadResponseAsync(TransactionChain chain, CancellationToken cancellationToken)
381:     {
382:         var legs = await dbContext.Transactions.AsNoTracking()
383:             .Where(t => t.ChainId == chain.Id)
384:             .Include(t => t.Entries).ThenInclude(e => e.Account)
385:             .OrderBy(t => t.Sequence)
386:             .ToListAsync(cancellationToken);
387:         var reversedBy = await dbContext.TransactionChains.AsNoTracking()
388:             .Where(c => c.ReversesChainId == chain.Id)
389:             .Select(c => c.Reference)
390:             .SingleOrDefaultAsync(cancellationToken);
391: 
392:         var legResponses = legs.Select(t =>
393:         {
394:             var debit = t.Entries.Single(e => e.EntryType == EntryType.Debit);
395:             var credit = t.Entries.Single(e => e.EntryType == EntryType.Credit);
396:             return new ChainLegResponse(t.Sequence!.Value, t.Purpose!.Value.ToString(), t.Reference,
397:                 debit.Account.AccountNumber, credit.Account.AccountNumber,
398:                 SupportedCurrencies.ToCurrencyScale(debit.Amount, debit.Currency), debit.Currency, t.Status.ToString());
399:         }).ToList();
400: 
401:         return ToResponse(chain, legResponses, chain.ReversesChain?.Reference, reversedBy);
402:     }
