156:             .Include(c => c.Legs).ThenInclude(l => l.Entries).ThenInclude(e => e.Account)
157:             .SingleOrDefaultAsync(c => c.Reference == reference, cancellationToken)
158:             ?? throw new ChainNotFoundException($"Chain '{reference}' was not found.");
159: 
160:         if (original.Status != TransactionStatus.Success)
161:             throw new ChainNotReversibleException(
162:                 $"Only successful chains can be reversed; '{original.Reference}' is {original.Status}.");
163:         if (original.ReversesChainId is not null)
164:             throw new ChainNotReversibleException(
165:                 $"'{original.Reference}' is itself a reversal and cannot be reversed.");
166: 
167:         //Insert the reversal chain first: the unique reverses_chain_id refuses a second reversal before any work
168:         var reversal = new TransactionChain
169:         {
170:             Reference = TransactionReference.Generate("CHN"),
171:             InitiatedBy = clientId,
172:             // Reversals carry no client key; a generated one keeps the (client, key) index from treating two
173:             // reversals by the same client as duplicates. reverses_chain_id is the real guard.
174:             IdempotencyKey = $"REVERSAL-{Guid.NewGuid()}",
175:             Status = TransactionStatus.Pending,
176:             Narration = reason ?? $"Reversal of {original.Reference}",
177:             ReversesChainId = original.Id,
178:             CreatedAt = now,
179:         };
180:         dbContext.TransactionChains.Add(reversal);
181:         try
182:         {
183:             await dbContext.SaveChangesAsync(cancellationToken);
184:         }
185:         catch (DbUpdateException ex) when (ex.InnerException is PostgresException
186:         {
187:             SqlState: PostgresErrorCodes.UniqueViolation, ConstraintName: ReversesChainIndex
188:         })
189:         {
190:             throw new ChainAlreadyReversedException($"Chain '{original.Reference}' has already been reversed.", ex);
191:         }
192: 
193:         //Lock the accounts the reversing legs debit (each original leg's credit side), once each, ascending order
194:         foreach (var number in original.Legs
195:                      .Select(l => l.Entries.Single(e => e.EntryType == EntryType.Credit).Account.AccountNumber)
196:                      .Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal))
197:         {
198:             await legPoster.LockAccountAsync(number, cancellationToken);
199:         }
200: 
201:         //Reverse each leg, last leg first (e.g. Tax, Fee, Principal)
202:         var reversingLegs = new List<ChainLegResponse>();
203:         var lastFirst = original.Legs.OrderByDescending(l => l.Sequence).ToList();
204:         for (var i = 0; i < lastFirst.Count; i++)
205:         {
206:             var originalLeg = lastFirst[i];
207:             var sequence = i + 1;
208:             var envelope = new Transaction
209:             {
210:                 Reference = TransactionReference.Generate(),
211:                 IdempotencyKey = $"chain:{reversal.Id}:{sequence}",
212:                 InitiatedBy = clientId,
213:                 Status = TransactionStatus.Pending,
214:                 Narration = reason ?? $"Reversal of {originalLeg.Reference}",
215:                 CreatedAt = now,
216:                 Chain = reversal,
217:                 Sequence = sequence,
218:                 Purpose = originalLeg.Purpose,
219:             };
220: 
221:             await legReverser.ReverseLegAsync(originalLeg, envelope, reason, now, cancellationToken);
222: 
223:             var originalDebit = originalLeg.Entries.Single(e => e.EntryType == EntryType.Debit);
224:             var originalCredit = originalLeg.Entries.Single(e => e.EntryType == EntryType.Credit);
225:             reversingLegs.Add(new ChainLegResponse(sequence, envelope.Purpose!.Value.ToString(), envelope.Reference,
226:                 originalCredit.Account.AccountNumber, originalDebit.Account.AccountNumber,
227:                 SupportedCurrencies.ToCurrencyScale(originalDebit.Amount, originalDebit.Currency), originalDebit.Currency,
228:                 envelope.Status.ToString()));
229:         }
230: 
231:         reversal.Status = TransactionStatus.Success;
232:         reversal.CompletedAt = DateTimeOffset.UtcNow;
233:         RecordChainAudit(reversal, AuditActions.ChainReversed, reversingLegs.Sum(l => l.Amount), reversingLegs[0].Currency);
234:         await dbContext.SaveChangesAsync(cancellationToken);
235: 
236:         return ToResponse(reversal, reversingLegs, reversesReference: original.Reference, reversedByReference: null);
237:     }
238: 
239:     private async Task<List<ChainLegResponse>> PostLegsAsync(
240:         TransactionChain chain, List<Leg> legs, string? narration, string? clientId, DateTimeOffset now, CancellationToken cancellationToken)
241:     {
242:         // Lock every debited account once, in ascending ordinal account-number order, before posting anything:
243:         // any two chains lock shared accounts in the same order, so they cannot deadlock (decision #45).
244:         // An account that does not exist is reported by LegPoster at its leg.
245:         var lockedPayers = new Dictionary<string, Account>(StringComparer.Ordinal);
246:         foreach (var number in legs.Select(l => l.Spec.DebitAccountNumber).Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal))
247:         {
248:             if (await legPoster.LockAccountAsync(number, cancellationToken) is { } account)
249:                 lockedPayers[number] = account;
250:         }
251: 
252:         // One balance per paying account, derived up front. Money a payer receives earlier in the same chain is
253:         // not counted: it must already afford everything it pays (decision #45).
254:         var available = new Dictionary<string, decimal>(StringComparer.Ordinal);
255:         foreach (var (number, account) in lockedPayers)
256:             available[number] = await legPoster.BalanceAsync(account, cancellationToken);
257:         var paid = new Dictionary<string, decimal>(StringComparer.Ordinal);
258: 
259:         string? chainCurrency = null;
260:         var posted = new List<ChainLegResponse>();
261:         for (var i = 0; i < legs.Count; i++)
262:         {
263:             var (spec, purpose) = legs[i];
264:             var sequence = i + 1;
265:             var leg = new Transaction
266:             {
267:                 Reference = TransactionReference.Generate(),
268:                 // Generated, so leg keys can never collide with a client's own keys (those may not start with "chain:").
269:                 IdempotencyKey = $"chain:{chain.Id}:{sequence}",
270:                 InitiatedBy = clientId,
271:                 Status = TransactionStatus.Pending,
272:                 Narration = narration is null ? purpose.ToString() : $"{narration} · {purpose}",
273:                 CreatedAt = now,
274:                 Chain = chain,
275:                 Sequence = sequence,
276:                 Purpose = purpose,
277:             };
278:             dbContext.Transactions.Add(leg);
279: 
280:             try
281:             {
282:                 // Per-leg rules, as for a transfer (decision #45); the payer's balance is checked below for the chain.
283:                 var debit = await legPoster.PostLegAsync(leg, spec, checkBalance: false, now, cancellationToken);
284:                 var credit = await dbContext.Accounts.SingleAsync(a => a.AccountNumber == spec.CreditAccountNumber, cancellationToken);
285: 
286:                 if (purpose is LegPurpose.Fee or LegPurpose.Tax && credit.AccountClass != AccountClass.System)
287:                     throw new LegRejectedException($"{purpose} legs must credit a system account");
288: 
289:                 chainCurrency ??= debit.CurrencyCode;
290:                 if (debit.CurrencyCode != chainCurrency)
291:                     throw new LegRejectedException("All legs in a chain must use the same currency");
292: 
293:                 var floor = LegPoster.FloorFor(debit)
294:                     ?? throw new LegRejectedException($"Unrecognized account class: {debit.AccountClass}");
295:                 paid[spec.DebitAccountNumber] = paid.GetValueOrDefault(spec.DebitAccountNumber) + spec.Amount;
296:                 if (available[spec.DebitAccountNumber] - paid[spec.DebitAccountNumber] < floor)
297:                     throw new LegRejectedException("Insufficient Account Balance");
298: 
299:                 // Audit, committed with the postings: the existing transfer action, one row per leg.
300:                 auditLogger.Record(new AuditLog
301:                 {
302:                     Action = AuditActions.Transfer,
303:                     EntityType = nameof(Transaction),
304:                     EntityId = leg.Reference,
305:                     DebitAccountNumber = spec.DebitAccountNumber,
306:                     CreditAccountNumber = spec.CreditAccountNumber,
307:                     Amount = spec.Amount,
308:                     Currency = debit.CurrencyCode,
309:                     Status = leg.Status.ToString(),
310:                 });
311: 
312:                 posted.Add(new ChainLegResponse(sequence, purpose.ToString(), leg.Reference, spec.DebitAccountNumber,
313:                     spec.CreditAccountNumber, SupportedCurrencies.ToCurrencyScale(spec.Amount, debit.CurrencyCode),
314:                     debit.CurrencyCode, leg.Status.ToString()));
315:             }
316:             catch (LegRejectedException rejected)
317:             {
318:                 throw new ChainRejectedException(sequence, rejected.Message);
319:             }
320: 
321:             // Save each leg, so its id exists and its entries are visible to later reads in this transaction.
322:             await dbContext.SaveChangesAsync(cancellationToken);
323:         }
324: 
325:         return posted;
326:     }
327: 
328:     // Second, small save after a rolled-back chain: store it as Failed with its audit row (decision #6). If a
329:     // same-key retry stored its own chain in the meantime, return that one instead.
330:     private async Task<ChainResponse> StoreFailedAsync(
331:         ChainRequest request, string? clientId, string requestHash, string reference, DateTimeOffset now,
332:         ChainRejectedException rejection, CancellationToken cancellationToken)
333:     {
334:         dbContext.ChangeTracker.Clear();
335:         var failed = new TransactionChain
336:         {
337:             Reference = reference,
338:             InitiatedBy = clientId,
339:             IdempotencyKey = request.IdempotencyKey,
340:             RequestHash = requestHash,
341:             Status = TransactionStatus.Failed,
342:             Narration = request.Narration,
343:             FailureReason = rejection.Message,
344:             FailedSequence = rejection.Sequence,
345:             CreatedAt = now,
346:             CompletedAt = DateTimeOffset.UtcNow,
347:         };
348:         dbContext.TransactionChains.Add(failed);
349:         RecordChainAudit(failed, AuditActions.ChainPosted, request.Legs.Sum(l => l.Amount), currency: null);
350: 
351:         try
352:         {
353:             await dbContext.SaveChangesAsync(cancellationToken);
354:         }
355:         catch (DbUpdateException ex) when (IsIdempotencyConflict(ex))
356:         {
357:             dbContext.ChangeTracker.Clear();
358:             return await ReplayAsync(clientId, request.IdempotencyKey, requestHash, cancellationToken);
359:         }
360: 
361:         return ToResponse(failed, [], reversesReference: null, reversedByReference: null);
362:     }
363: 
364:     // The key is already taken by this client: same legs -> the stored chain; different legs -> 409.
365:     private async Task<ChainResponse> ReplayAsync(
366:         string? clientId, string idempotencyKey, string requestHash, CancellationToken cancellationToken)
367:     {
368:         dbContext.ChangeTracker.Clear();
369:         var stored = await dbContext.TransactionChains.AsNoTracking()
370:             .Include(c => c.ReversesChain)
371:             .SingleAsync(c => c.InitiatedBy == clientId && c.IdempotencyKey == idempotencyKey, cancellationToken);
372: 
373:         if (stored.RequestHash != requestHash)
374:             throw new DuplicateIdempotencyKeyException(
375:                 $"Idempotency key '{idempotencyKey}' was already used for a different request.");
376: 
377:         return await LoadResponseAsync(stored, cancellationToken);
378:     }
379: 
380:     private async Task<ChainResponse> LoadResponseAsync(TransactionChain chain, CancellationToken cancellationToken)
381:     {
382:         var legs = await dbContext.Transactions.AsNoTracking()
383:             .Where(t => t.ChainId == chain.Id)
384:             .Include(t => t.Entries).ThenInclude(e => e.Account)
385:             .OrderBy(t => t.Sequence)
386:             .ToListAsync(cancellationToken);
387:         var reversedBy = await dbContext.TransactionChains.AsNoTracking()
388:             .Where(c => c.ReversesChainId == chain.Id)
389:             .Select(c => c.Reference)
390:             .SingleOrDefaultAsync(cancellationToken);
391: 
392:         var legResponses = legs.Select(t =>
393:         {
394:             var debit = t.Entries.Single(e => e.EntryType == EntryType.Debit);
395:             var credit = t.Entries.Single(e => e.EntryType == EntryType.Credit);
396:             return new ChainLegResponse(t.Sequence!.Value, t.Purpose!.Value.ToString(), t.Reference,
397:                 debit.Account.AccountNumber, credit.Account.AccountNumber,
398:                 SupportedCurrencies.ToCurrencyScale(debit.Amount, debit.Currency), debit.Currency, t.Status.ToString());
399:         }).ToList();
400: 
401:         return ToResponse(chain, legResponses, chain.ReversesChain?.Reference, reversedBy);
402:     }
403: 
404:     private static ChainResponse ToResponse(
405:         TransactionChain chain, IReadOnlyList<ChainLegResponse> legs, string? reversesReference, string? reversedByReference) =>
406:         new(chain.Reference, chain.Status.ToString(), chain.Narration, chain.FailureReason, chain.FailedSequence,
407:             reversesReference, reversedByReference, chain.CreatedAt, chain.CompletedAt, legs);
408: 
409:     private void RecordChainAudit(TransactionChain chain, string action, decimal totalAmount, string? currency) =>
410:         auditLogger.Record(new AuditLog
411:         {
412:             Action = action,
413:             EntityType = nameof(TransactionChain),
414:             EntityId = chain.Reference,
415:             Amount = totalAmount,
416:             Currency = currency,
417:             Status = chain.Status.ToString(),
418:         });
419: 
420:     // SHA-256 of the ordered legs as [debit, credit, amount (G29, so 100 = 100.00), purpose]. Narration is left
421:     // out, as for transfers (decision #44).
422:     private static string HashLegs(IEnumerable<Leg> legs) =>
423:         Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(
424:             legs.Select(l => new[]
425:             {
426:                 l.Spec.DebitAccountNumber,
427:                 l.Spec.CreditAccountNumber,
428:                 l.Spec.Amount.ToString("G29", CultureInfo.InvariantCulture),
429:                 l.Purpose.ToString(),
430:             })))));
431: 
432:     private static bool IsIdempotencyConflict(DbUpdateException ex) =>
433:         ex.InnerException is PostgresException { SqlState: PostgresErrorCodes.UniqueViolation, ConstraintName: IdempotencyIndex };
434: 
435:     // Cleanup, not work: runs even if the client disconnected (see TransferService).
436:     private static Task RollbackAsync(IDbContextTransaction dbTransaction) =>
437:         dbTransaction.RollbackAsync(CancellationToken.None);
438: }

