5: // One rule for every idempotency key: short enough to always fit the unique index (Postgres rejects index
6: // entries over ~2.7 KB with a 500), and limited to characters that are safe in logs and URLs.
7: public static partial class IdempotencyKeyRule
8: {
9:     public const int MaxLength = 128;
10: 
11:     // Chain legs get generated keys "chain:{chainId}:{sequence}" (decision #45); clients may not use the prefix.
12:     public const string ReservedPrefix = "chain:";
13: 
14:     // \z, not $: in .NET, $ also matches just before a trailing newline, so "abc\n" would pass.
15:     [GeneratedRegex(@"^[A-Za-z0-9._:-]{1,128}\z")]
16:     private static partial Regex Pattern();
17: 
18:     public static string? Validate(string? key) =>
19:         string.IsNullOrWhiteSpace(key) ? "IdempotencyKey is required."
20:         : !Pattern().IsMatch(key) ? $"IdempotencyKey must be 1-{MaxLength} characters: letters, digits, '-', '_', '.' or ':'."
21:         : key.StartsWith(ReservedPrefix, StringComparison.OrdinalIgnoreCase) ? $"IdempotencyKey must not start with '{ReservedPrefix}': it is reserved for chain legs."
22:         : null;
23: }

