4: namespace LedgerApi.Middleware;
5: 
6: public class ExceptionHandlingMiddleware(RequestDelegate next, ILogger<ExceptionHandlingMiddleware> logger)
7: {
8:     public async Task InvokeAsync(HttpContext context)
9:     {
10:         try
11:         {
12:             await next(context);
13:         }
14:         catch (OperationCanceledException) when (context.RequestAborted.IsCancellationRequested)
15:         {
16:             logger.LogInformation("Request cancelled by client: {Method} {Path}", context.Request.Method, context.Request.Path);
17:         }
18:         catch (Exception ex) when (!context.Response.HasStarted)
19:         {
20:             var (status, title) = Map(ex);
21:             var isExpected = status != StatusCodes.Status500InternalServerError;
22: 
23:             if (isExpected)
24:                 logger.LogWarning(ex, "Request rejected ({Status}) {Method} {Path}", status, context.Request.Method, context.Request.Path);
25:             else
26:                 logger.LogError(ex, "Unhandled exception processing {Method} {Path}", context.Request.Method, context.Request.Path);
27: 
28:             context.Response.StatusCode = status;
29:             // contentType is passed explicitly: WriteAsJsonAsync would otherwise overwrite it with application/json.
30:             await context.Response.WriteAsJsonAsync(
31:                 new ProblemDetails
32:                 {
33:                     Status = status,
34:                     Title = title,
35:                     // Only expected business errors expose their message; unexpected ones must not leak internals.
36:                     Detail = isExpected ? ex.Message : null,
37:                     // Lets a client quote the id when reporting a problem; it matches the logs and audit rows.
38:                     Extensions = { ["correlationId"] = context.TraceIdentifier }
39:                 },
40:                 options: null,
41:                 contentType: "application/problem+json");
42:         }
43:     }
44: 
45:     private static (int Status, string Title) Map(Exception ex) => ex switch
46:     {
47:         AccountNotFoundException => (StatusCodes.Status404NotFound, "Account not found."),
48:         TransactionNotFoundException => (StatusCodes.Status404NotFound, "Transaction not found."),
49:         ChainNotFoundException => (StatusCodes.Status404NotFound, "Chain not found."),
50:         ChainNotReversibleException => (StatusCodes.Status422UnprocessableEntity, "Chain cannot be reversed."),
51:         TransactionNotReversibleException => (StatusCodes.Status422UnprocessableEntity, "Transaction cannot be reversed."),
52:         DuplicateIdempotencyKeyException => (StatusCodes.Status409Conflict, "Duplicate idempotency key."),
53:         ChainAlreadyReversedException => (StatusCodes.Status409Conflict, "Chain has already been reversed."),
54:         AlreadyReversedException => (StatusCodes.Status409Conflict, "Transaction has already been reversed."),
55:         InsufficientFundsException => (StatusCodes.Status422UnprocessableEntity, "Insufficient funds."),
56:         CurrencyMismatchException => (StatusCodes.Status422UnprocessableEntity, "Currency mismatch."),
57:         InvalidAccountStatusException => (StatusCodes.Status422UnprocessableEntity, "Account status does not allow this operation."),
58:         _ => (StatusCodes.Status500InternalServerError, "An unexpected error occurred.")
59:     };
60: }

