6: public class AuditLogger(LedgerDbContext dbContext, IHttpContextAccessor httpContextAccessor) : IAuditLogger
7: {
8:     private const int MaxUserAgentLength = 512;
9: 
10:     public AuditLog Record(AuditLog entry)
11:     {
12:         // Request details are filled in here so callers only describe the business change.
13:         // Outside an HTTP request (e.g. tests, future background jobs) they stay null.
14:         var httpContext = httpContextAccessor.HttpContext;
15:         if (httpContext is not null)
16:         {
17:             entry.ActorId ??= httpContext.User.Identity?.Name;
18:             entry.CorrelationId = httpContext.TraceIdentifier;
19:             entry.Endpoint = $"{httpContext.Request.Method} {httpContext.Request.Path}";
20:             entry.IpAddress = httpContext.Connection.RemoteIpAddress?.ToString();
21: 
22:             var userAgent = httpContext.Request.Headers.UserAgent.ToString();
23:             entry.UserAgent = userAgent.Length switch
24:             {
25:                 0 => null,
26:                 > MaxUserAgentLength => userAgent[..MaxUserAgentLength],
27:                 _ => userAgent
28:             };
29:         }
30: 
31:         entry.CreatedAt = DateTimeOffset.UtcNow;
32:         dbContext.AuditLogs.Add(entry);
33:         return entry;
34:     }
35: }

